import { createServer } from "node:http";

const server = createServer((request, response) => {
  response.writeHead(200, { "Content-Type": "application/json" });
  response.end(JSON.stringify({ message: "Facts API is running" }));
});

server.listen(3000, () => {
  console.log("http://localhost:3000");
});

const facts = [
  { id: 1, topic: "HTML", statement: "HTML describes page structure." }
];

if (request.method === "GET" && request.url === "/api/facts") {
  response.writeHead(200, { "Content-Type": "application/json" });
  response.end(JSON.stringify(facts));
  return;
}

response.writeHead(404, { "Content-Type": "application/json" });
response.end(JSON.stringify({ error: "Route not found" }));

async function readJson(request) {
  let body = "";

  for await (const chunk of request) {
    body += chunk;
    if (body.length > 10_000) throw new Error("Body too large");
  }

  return JSON.parse(body);
}

const input = await readJson(request);

if (!input.topic?.trim() || !input.statement?.trim()) {
  sendJson(response, 400, { error: "topic and statement are required" });
  return;
}

const fact = {
  id: crypto.randomUUID(),
  topic: input.topic.trim(),
  statement: input.statement.trim()
};

facts.push(fact);
sendJson(response, 201, fact);
